corrected_code:
from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

router = APIRouter(prefix="/quic/webtransport")

class WebTransportStreamReadRequest(BaseModel):
    session_id: str
    stream_id: int

@router.post("/read-stream")
async def read_webtransport_stream_buffer(
    payload: WebTransportStreamReadRequest,
    session_manager: WebTransportSessionManager = Depends(get_wt_session_manager),
    current_user: User = Depends(get_current_user)
):
    session = session_manager.get_session(payload.session_id)
    if not session:
        raise HTTPException(status_code=404, detail="WebTransport session not found")

    if session.tenant_id != current_user.tenant_id:
        raise HTTPException(status_code=403, detail="Forbidden: Session belongs to another tenant")

    stream_buffer = session.get_stream_buffer(payload.stream_id)
    if stream_buffer is None:
        raise HTTPException(status_code=404, detail="Stream ID not found in session")

    data = stream_buffer.read()
    return {"session_id": payload.session_id, "stream_id": payload.stream_id, "data_hex": data.hex()}
